package fmp4

import (
	"bytes"
	"encoding/hex"
	"errors"
	"github.com/GregoryGost/gost-restreamer/internal/core"
	"github.com/GregoryGost/gost-restreamer/internal/media"
	"github.com/GregoryGost/gost-restreamer/internal/media/codec"
	"os"
	"testing"
)

// TestSDRContainerDescriptorsAndRawRoundTrip проверяет реальные AV1/H.264 всех программных
// профилей: исходные av1C/avcC, плоскости/глубина и знаковые времена сохраняются точно.
// Присутствующий nclx обязан совпадать с CICP 4/4/4 настоящего потока.
// Эталоны FFmpeg 7.1.5 получены из красного кадра 128×128/30 и отдельно декодированы с -xerror.
func TestSDRContainerDescriptorsAndRawRoundTrip(t *testing.T) {
	// fixture задаёт ожидаемые свойства и неизменённые заголовки и AU выбранного кодировщика.
	for _, fixture := range []struct {
		// name описывает реальный профиль и глубину эталона.
		name string
		// videoCodec задаёт сжатый видеокодек.
		videoCodec core.Codec
		// headers и au содержат исходные hex байты без повторного кодирования.
		headers, au string
	}{
		{"av1/main/yuv420p", core.CodecAV1, "81000c000a0d0000000337ffe6d7cc82020202", "0a0d0000000337ffe6d7cc8202020232191000836000008000000000ebc8e585f1278f4eb7b6107d6580"},
		{"av1/main/yuv420p10le", core.CodecAV1, "81004c000a0d0000000337ffe6d7ce82020202", "0a0d0000000337ffe6d7ce8202020232191000846000008000000000ebc8e585f1278f4eb7b601cce580"},
		{"av1/main/gray", core.CodecAV1, "81001c000a0d0000000337ffe6d7cd82020210", "0a0d0000000337ffe6d7cd82020210320e1000836000020000015600a37710"},
		{"av1/high/yuv444p", core.CodecAV1, "812000000a0d2000000337ffe6d7cd04040410", "0a0d2000000337ffe6d7cd0404041032191000836000008000000000ebc8e581d5ccf27df805dea09cb7"},
		{"av1/high/yuv444p10le", core.CodecAV1, "812040000a0d2000000337ffe6d7cf04040410", "0a0d2000000337ffe6d7cf0404041032191000846000008000000000ebc8e581d5ccf27df805de8f9bb7"},
		{"av1/professional/yuv422p", core.CodecAV1, "814008000a0d4000000337ffe6d7cc82020208", "0a0d4000000337ffe6d7cc8202020832191000836000008000000000ebc8e581d5ccf259c1b8ef2afc7c"},
		{"av1/professional/yuv422p10le", core.CodecAV1, "814048000a0d4000000337ffe6d7ce41010104", "0a0d4000000337ffe6d7ce4101010432191000846000008000000000ebc8e581d5ccf259c1b8eef2ba7c"},
		{"h264/baseline/yuv420p", core.CodecH264, "0142c00bffe1001a6742c00bda0811b016a0808088000003000800000301e078a15501000568ce0b2c80", ""},
		{"h264/main/yuv420p", core.CodecH264, "014d400bffe1001a674d400bda0811b016a0808088000003000800000301e078a15501000568ef0b2c80", ""},
		{"h264/high/yuv420p", core.CodecH264, "0164000bffe1001b6764000bacb41023602d41010110000003001000000303c0f142aa01000568ef0b2c8bfdf8f800", ""},
		{"h264/high10/yuv420p10le", core.CodecH264, "016e000bffe1001c676e000ba6cb41023602d41010110000030001000003003c0f142aa001000568ef0b2c8bfdfafa00", ""},
		{"h264/high422/yuv422p", core.CodecH264, "017a000bffe1001b677a000bbcb41023602d41010110000003001000000303c0f142aa01000568ef0b2c8bfef8f800", ""},
		{"h264/high422/yuv422p10le", core.CodecH264, "017a000bffe1001c677a000bb6cb41023602d41010110000030001000003003c0f142aa001000568ef0b2c8bfefafa00", ""},
		{"h264/high444/yuv444p", core.CodecH264, "01f4000bffe1001c67f4000b919682046c05a8202022000003000200000300781e28554001000668ef0b112110fff8f800", ""},
		{"h264/high444/yuv444p10le", core.CodecH264, "01f4000bffe1001b67f4000b90d9682046c05a82020220000003002000000781e2855401000668ef0b112110fffafa00", ""},
	} {
		t.Run(fixture.name, func(t *testing.T) {
			// Подтест публикует и читает единственный настоящий независимый AU с его исходными заголовками.
			// headers и err содержат конфигурацию и возможную ошибку записи hex.
			headers, err := hex.DecodeString(fixture.headers)
			if err != nil {
				t.Fatal(err)
			}
			// au содержит полный исходный AU, включая служебные NAL/OBU.
			au, err := hex.DecodeString(fixture.au)
			if err != nil {
				t.Fatal(err)
			}
			// actual хранит подтверждённый заголовками и первым AU формат.
			var actual core.VideoFormat
			if fixture.videoCodec == core.CodecAV1 {
				actual, _, err = codec.InspectAV1TU(headers, au, core.FrameRate{Numerator: 30, Denominator: 1})
			} else {
				actual, err = codec.H264Format(codec.VideoDescription{Headers: headers, Width: 128, Height: 128})
			}
			if err != nil {
				t.Fatal(err)
			}
			// init содержит общую эпоху и сдвиг, позволяющий хранить отрицательные времена обеих дорожек.
			init := testInit(t)
			// video сохраняет реальную конфигурацию с частотой шкалы 30 Гц.
			video, err := media.NewCodecConfig(media.CodecConfigInfo{Track: media.TrackVideo, SourceEpoch: 11, Revision: 2, TimeBase: media.TimeBase{Numerator: 1, Denominator: 30}, Video: actual}, headers)
			if err != nil {
				t.Fatal(err)
			}
			init.Video = video
			// wire принимает локальный контейнер; m создаёт сериализатор и проверяет соответствие описания заголовкам до записи.
			var wire bytes.Buffer
			m, err := NewMuxer(&wire, init, testLimits())
			if err != nil {
				t.Fatal(err)
			}
			// original содержит полную единицу с отрицательными DTS/PTS и независимым стартом.
			original := packet(t, video, media.PacketInfo{DTS: -1, PTS: -1, DurationTicks: 1, Keyframe: true}, au)
			if err = m.WritePacket(original); err != nil {
				t.Fatal(err)
			}
			// ffmpeg при явном включении проверяет настоящее декодирование контейнера с исходным AU.
			if ffmpeg := os.Getenv("GOST_FMP4_FFMPEG"); ffmpeg != "" {
				// decoded содержит контрольные суммы ровно одного декодированного видеокадра.
				decoded := runMediaCommand(t, ffmpeg, wire.Bytes(), "-v", "error", "-xerror", "-i", "pipe:0", "-map", "0:v:0", "-f", "framemd5", "pipe:1")
				if bytes.Count(decoded, []byte("\n0,")) != 1 {
					t.Fatal("Не декодирован ровно один кадр", string(decoded))
				}
			}
			// d читает тот же init и проверяет все поля исходных заголовков и colr.
			d, err := NewDemuxer(bytes.NewReader(wire.Bytes()), DemuxOptions{Limits: testLimits()})
			if err != nil {
				t.Fatal(err)
			}
			// got содержит прочитанный AU с исходными знаковыми временами и неизменёнными данными.
			got, err := d.Next()
			if err != nil {
				t.Fatal(err)
			}
			if got.Info() != original.Info() || !bytes.Equal(got.Payload(), au) || !sameConfig(got.Config(), video) {
				t.Fatal("Изменены AU/config/time")
			}
			// desc подтверждает сохранение прежнего расположения блоков: Muxer не добавляет отсутствующий colr.
			for _, desc := range d.Descriptions() {
				if desc.Track == media.TrackVideo && desc.Color != nil {
					t.Fatal("Самопроизвольно добавлен colr")
				}
			}
			// colored добавляет независимо построенный nclx в настоящую запись видеодорожки для проверки Demuxer.
			colored := injectSampleEntryColor(t, wire.Bytes(), []byte{'n', 'c', 'l', 'x', 0, 4, 0, 4, 0, 4, 0})
			if _, err = NewDemuxer(bytes.NewReader(colored), DemuxOptions{Limits: testLimits()}); err != nil {
				t.Fatal("Согласованный colr отвергнут", err)
			}
			// damaged содержит тот же контейнер с заведомо ложным кодом матрицы в colr.
			damaged := bytes.Clone(colored)
			// position определяет тело единственного nclx среди корректных исходных блоков.
			position := bytes.Index(damaged, []byte("nclx"))
			if position < 0 {
				t.Fatal("Отсутствует colr")
			}
			damaged[position+9] = 5
			if _, err = NewDemuxer(bytes.NewReader(damaged), DemuxOptions{Limits: testLimits()}); !errors.Is(err, ErrInvalid) {
				t.Fatal("Принято расхождение colr/SPS/sequence", err)
			}

			// mismatch объявляет ложные плоскости при сохранении реальных avcC/av1C.
			mismatch := video.Info()
			mismatch.Video.PixelFormat = "yuv420p"
			if actual.PixelFormat == "yuv420p" {
				mismatch.Video.PixelFormat = "yuv444p"
			}
			init.Video, err = media.NewCodecConfig(mismatch, headers)
			if err != nil {
				t.Fatal(err)
			}
			wire.Reset()
			if _, err = NewMuxer(&wire, init, testLimits()); !errors.Is(err, ErrInvalid) || wire.Len() != 0 {
				t.Fatal("Ложные плоскости опубликованы", err)
			}
		})
	}
}

// injectSampleEntryColor вставляет независимо заданный colr в видеозапись data и пересчитывает
// размеры только её родительских блоков. Тестовый контейнер использует восьмибайтовые заголовки
// и смещения фрагментов относительно moof, поэтому абсолютные позиции AU менять не требуется.
func injectSampleEntryColor(t *testing.T, data, color []byte) []byte {
	t.Helper()
	// boxes содержит проверенные блоки текущего уровня; err сообщает об ошибке исходного тестового контейнера.
	boxes, err := children(data)
	if err != nil {
		t.Fatal(err)
	}
	// parts накапливает повторно обрамлённые блоки с одним новым цветовым дескриптором.
	var parts [][]byte
	// b выбирает очередной контейнер либо исходный конечный блок.
	for _, b := range boxes {
		// body сохраняет исходное тело либо заменяется рекурсивно пересобранными дочерними блоками.
		body := b.data
		switch b.kind {
		case "moov", "trak", "mdia", "minf", "stbl":
			body = injectSampleEntryColor(t, body, color)
		case "stsd":
			if len(body) < 8 {
				t.Fatal("Усечён stsd")
			}
			body = join(body[:8], injectSampleEntryColor(t, body[8:], color))
		case "avc1", "av01":
			body = join(body, box("colr", color))
		}
		parts = append(parts, box(b.kind, body))
	}
	return join(parts...)
}
